// TEMPORARY: benchmarks node_modules cache archive formats. Remove before merging.
// Run from the repository root after the node_modules cache was restored and extracted.
// Each variant extracts into an empty folder, as the PR jobs do, except on macOS, whose runners
// have little disk space: there it replaces the node_modules folders of the repository.

import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';

const root = process.cwd();
const isWindows = process.platform === 'win32';
const inPlace = process.env.BENCH_IN_PLACE ? process.env.BENCH_IN_PLACE === '1' : process.platform === 'darwin';
const scriptsOnly = process.env.BENCH_SCRIPTS_ONLY === '1';
const work = path.join(root, '.build', 'bench');
fs.rmSync(work, { recursive: true, force: true });
fs.mkdirSync(work, { recursive: true });

function run(command: string, cwd: string): Promise<void> {
	return new Promise((resolve, reject) => {
		const child = spawn(command, { cwd, shell: true, stdio: ['ignore', 'ignore', 'pipe'] });
		let stderr = '';
		child.stderr.on('data', data => { stderr += data; });
		child.on('close', code => code === 0 ? resolve() : reject(new Error(`${command} exited with ${code}: ${stderr.slice(-2000)}`)));
	});
}

async function timed(commands: string[], cwd: string): Promise<number> {
	const start = Date.now();
	await Promise.all(commands.map(command => run(command, cwd)));
	return (Date.now() - start) / 1000;
}

await run(`node build/azure-pipelines/common/listNodeModules.ts .build/bench/list.txt`, root);
const list = fs.readFileSync(path.join(work, 'list.txt'), 'utf8').split('\n').filter(Boolean);
// The outermost node_modules folder of each entry, relative to the repository root.
const nodeModulesDirs = [...new Set(list.map(file => {
	const segments = file.split('/');
	return segments.slice(0, segments.indexOf('node_modules') + 1).join('/');
}))];
const weights = list.map(file => {
	try {
		const stat = fs.lstatSync(path.join(root, file));
		return (stat.isFile() ? stat.size : 0) + 16384;
	} catch {
		return 16384;
	}
});
const totalWeight = weights.reduce((a, b) => a + b, 0);

/** Counts the files and links in the node_modules folders under the given folder. */
function countEntries(base: string): number {
	let count = 0;
	const stack = nodeModulesDirs.map(dir => path.join(base, dir)).filter(dir => fs.existsSync(dir));
	while (stack.length) {
		const current = stack.pop()!;
		for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
			if (entry.isDirectory()) {
				stack.push(path.join(current, entry.name));
			} else {
				count++;
			}
		}
	}
	return count;
}

/** Returns an empty folder to extract into: a new one, or the repository root without its node_modules folders. */
function prepareTarget(name: string): string {
	if (inPlace) {
		for (const dir of nodeModulesDirs) {
			fs.rmSync(path.join(root, dir), { recursive: true, force: true, maxRetries: 5 });
		}
		return root;
	}
	const target = path.join(work, `${name}-out`);
	fs.mkdirSync(target, { recursive: true });
	return target;
}

function split(parts: number): string[][] {
	const result: string[][] = Array.from({ length: parts }, () => []);
	let accumulated = 0;
	list.forEach((file, index) => {
		result[Math.min(parts - 1, Math.floor(accumulated / (totalWeight / parts)))].push(file);
		accumulated += weights[index];
	});
	return result;
}

interface IFormat {
	readonly extension: string;
	archive(listFile: string, archive: string): string;
	extract(archive: string): string;
}

const sevenZip = (level: number): IFormat => ({
	extension: '7z',
	archive: (listFile, archive) => `7z.exe a "${archive}" -mx${level} "@${listFile}"`,
	extract: archive => `7z.exe x "${archive}" -aoa -y`,
});
const windowsTarZstd: IFormat = {
	extension: 'tzst',
	archive: (listFile, archive) => `C:\\Windows\\System32\\tar.exe -cf - -T "${listFile}" | zstd -3 -T0 -q -f -o "${archive}"`,
	extract: archive => `zstd -d -c -q "${archive}" | C:\\Windows\\System32\\tar.exe -xf -`,
};
const unixTarZstd: IFormat = {
	extension: 'tzst',
	archive: (listFile, archive) => `tar --use-compress-program='zstd -T0 -3' -cf "${archive}" --files-from "${listFile}"`,
	extract: archive => `tar --use-compress-program='zstd -d -T0' -xf "${archive}"`,
};

const results: Record<string, unknown>[] = [];

function record(result: Record<string, unknown>) {
	console.log(JSON.stringify(result));
	results.push(result);
}

async function variant(name: string, parts: number, format: IFormat) {
	const dir = path.join(work, name);
	fs.mkdirSync(dir, { recursive: true });
	const lists = split(parts);
	const archives = lists.map((_, index) => path.join(dir, `part-${index}.${format.extension}`));
	lists.forEach((files, index) => fs.writeFileSync(path.join(dir, `list-${index}.txt`), files.join('\n') + '\n'));
	try {
		const archiveSeconds = await timed(lists.map((_, index) => format.archive(path.join(dir, `list-${index}.txt`), archives[index])), root);
		const target = prepareTarget(name);
		const extractSeconds = await timed(archives.map(archive => format.extract(archive)), target);
		const sizeMB = Math.round(archives.reduce((sum, archive) => sum + fs.statSync(archive).size, 0) / 1024 / 1024);
		record({ name, parts, extractSeconds, archiveSeconds, sizeMB, entries: countEntries(target), expectedEntries: list.length });
	} catch (error) {
		console.log(`${name}: failed: ${error}`);
		results.push({ name, parts, error: String(error).slice(0, 500) });
	}
	fs.rmSync(dir, { recursive: true, force: true, maxRetries: 5 });
}

// The archive that the cache action restored, as the PR jobs extract it today.
{
	const archive = path.join(root, '.build/node_modules_cache', isWindows ? 'cache.7z' : 'node-modules.tzst');
	const format = isWindows ? sevenZip(3) : unixTarZstd;
	const target = prepareTarget('current');
	const extractSeconds = await timed([format.extract(archive)], target);
	record({ name: 'current', parts: 1, extractSeconds, sizeMB: Math.round(fs.statSync(archive).size / 1024 / 1024), entries: countEntries(target), expectedEntries: list.length });
}

if (!scriptsOnly) {
	if (isWindows) {
		for (const parts of [4, 8, 16]) {
			await variant(`7z-mx3-x${parts}`, parts, sevenZip(3));
		}
		await variant('7z-mx0-x8', 8, sevenZip(0));
		await variant('tar-zstd-x1', 1, windowsTarZstd);
	} else {
		for (const parts of [4, 8, 16]) {
			await variant(`tar-zstd-x${parts}`, parts, unixTarZstd);
		}
	}
}
if (isWindows) {
	await variant('tar-zstd-x8', 8, windowsTarZstd);
}

// The cache scripts of this branch: archive as pr-node-modules.yml does, and extract as the PR jobs do.
{
	const scripts = path.join(root, '.github/workflows/node_modules_cache');
	const script = isWindows ? `pwsh -NoProfile -File "${path.join(scripts, 'cache.ps1')}"` : `"${path.join(scripts, 'cache.sh')}"`;
	const cacheFolder = path.join(root, '.build', 'node_modules_cache');
	try {
		const archiveSeconds = await timed([`${script} archive`], root);
		const archives = fs.readdirSync(cacheFolder).filter(file => /^(cache-\d+\.7z|node-modules-\d+\.tzst)$/.test(file));
		const sizeMB = Math.round(archives.reduce((sum, file) => sum + fs.statSync(path.join(cacheFolder, file)).size, 0) / 1024 / 1024);
		const target = prepareTarget('cache-scripts');
		if (target !== root) {
			// The extract scripts read the archives, and on Windows a helper, relative to the current folder.
			fs.mkdirSync(path.join(target, '.build', 'node_modules_cache'), { recursive: true });
			for (const file of archives) {
				fs.renameSync(path.join(cacheFolder, file), path.join(target, '.build', 'node_modules_cache', file));
			}
			fs.mkdirSync(path.join(target, 'build', 'azure-pipelines', 'win32'), { recursive: true });
			fs.copyFileSync(path.join(root, 'build/azure-pipelines/win32/exec.ps1'), path.join(target, 'build/azure-pipelines/win32/exec.ps1'));
		}
		const extractSeconds = await timed([`${script} extract`], target);
		record({ name: 'cache-scripts', parts: archives.length, extractSeconds, archiveSeconds, sizeMB, entries: countEntries(target), expectedEntries: list.length });
	} catch (error) {
		console.log(`cache-scripts: failed: ${error}`);
		results.push({ name: 'cache-scripts', parts: 0, error: String(error).slice(0, 500) });
		process.exitCode = 1;
	}
}

const table = [
	`### node_modules cache benchmark (${process.platform}, ${list.length} entries, ${inPlace ? 'in place' : 'into empty folders'})`,
	'',
	'| variant | parts | extract (s) | archive (s) | size (MB) | entries | expected |',
	'|---|---|---|---|---|---|---|',
	...results.map(r => `| ${r.name} | ${r.parts} | ${typeof r.extractSeconds === 'number' ? r.extractSeconds.toFixed(1) : 'failed'} | ${typeof r.archiveSeconds === 'number' ? r.archiveSeconds.toFixed(1) : ''} | ${r.sizeMB ?? ''} | ${r.entries ?? ''} | ${r.expectedEntries ?? ''} |`),
	'',
].join('\n');
console.log(table);
if (process.env.GITHUB_STEP_SUMMARY) {
	fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, table);
}
